"""Week 7 Day 1 (designing an A/B test) as eight ```story blocks, English and Russian from one source (the founder, 2026-11-01).
Build once: python -I scripts/stories/rebuild.py w7d1 · after that: python -I scripts/stories/apply.py w7d1.
Pictures: ivs (story2.js), dots / hist (story.js), hash / days / peekd / design (docs/assets/story5.js). Numbers: the page, or
computed here (the hashes and the hash strip from data/ab/aa_users.csv) and checked with Python."""
import csv, hashlib, os
from common import build as _b, btn

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
AA_SALT, V2_SALT = "offer_screen_aa_2026_07", "offer_screen_v2"
IDS = [925601, 665666, 652995, 774155, 376261, 859393]          # the page's picture: B A A B A A with the A/A salt


def sha(salt, uid):
    return hashlib.sha256(f"{salt}{uid}".encode()).hexdigest()


def arm(salt, uid):
    return "A" if int(sha(salt, uid), 16) % 2 == 0 else "B"


ROWS_AA = [[u, sha(AA_SALT, u)] for u in IDS]
ROWS_V2 = [[u, sha(V2_SALT, u)] for u in IDS]
CHANGED = [i for i, u in enumerate(IDS) if arm(AA_SALT, u) != arm(V2_SALT, u)]
assert [arm(AA_SALT, u) for u in IDS] == list("BAABAA") and CHANGED == [1, 2, 4]
with open(os.path.join(ROOT, "data", "ab", "aa_users.csv"), newline="") as fh:
    FIRST100 = [int(r["user_id"]) for _, r in zip(range(100), csv.DictReader(fh))]
STRIP = [round(int(sha(AA_SALT, u), 16) / 2 ** 256, 4) for u in FIRST100]
LEFT_HALF = sum(v < 0.5 for v in STRIP)
RIGHT_90 = sum(v >= 0.9 for v in STRIP)

AXIS_GAP = ("gap B − A, points", "разрыв B − A, пункты")
REAL_OR_NOT = (["a real experiment", "not an experiment"], ["настоящий эксперимент", "не эксперимент"])
DESIGN = [[("Who sees B?", "Кто видит B?"), (["next month's users", "another channel", "a coin: the hash"], ["следующий месяц", "другой канал", "монетка: хеш"])],
          [("The coin flips per…", "Монетку бросают на…"), (["session", "user"], ["сессию", "пользователя"])],
          [("The result is read…", "Итог смотрят…"), (["every morning", "once, at the end"], ["каждое утро", "один раз, в конце"])]]
DESIGN_LABELS = ([[q[0], a[0]] for q, a in DESIGN], [[q[1], a[1]] for q, a in DESIGN])


def act(do, en, ru, rep=1, n=0, **kw):   # a button that is not "run n": hash, stop
    return btn(n, en, ru, rep, do=do, **kw)


